const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
function tr(key){return (state.lang==="fa"?fa:en)[key]||key}
function applyStaticCopy(){const inverse=Object.fromEntries(Object.entries(staticEn).map(([a,b])=>[b,a]));const map=state.lang==="en"?staticEn:inverse;const phrases=Object.entries(map).sort((a,b)=>b[0].length-a[0].length);const walk=document.createTreeWalker(document.body,NodeFilter.SHOW_TEXT);let node;while((node=walk.nextNode())){const parent=node.parentElement;if(!parent||parent.closest("[data-i18n],script,style"))continue;const original=node.nodeValue;if(!original.trim())continue;let translated=original;if(!parent.closest("code")){for(const [source,target] of phrases)translated=translated.replaceAll(source,target)}translated=state.lang==="en"?translated.replace(/[۰-۹٠-٩]/g,d=>{const i="۰۱۲۳۴۵۶۷۸۹".indexOf(d);return i>=0?String(i):String("٠١٢٣٤٥٦٧٨٩".indexOf(d))}):translated.replace(/[0-9]/g,d=>"۰۱۲۳۴۵۶۷۸۹"[Number(d)]);node.nodeValue=translated}}
function localize(){document.documentElement.lang=state.lang;document.documentElement.dir=state.lang==="fa"?"rtl":"ltr";document.body.classList.toggle("is-en",state.lang==="en");$$("[data-i18n]").forEach(el=>el.textContent=tr(el.dataset.i18n));$$("[data-placeholder-fa]").forEach(el=>el.placeholder=state.lang==="fa"?el.dataset.placeholderFa:el.dataset.placeholderEn);$("#languageLabel").textContent=state.lang==="fa"?"English":"فارسی";$("#workspaceName").textContent=state.role==="admin"?(state.lang==="fa"?"مدیریت مادر":"Mother panel"):state.role==="reseller"?tr("reseller_workspace"):tr("partner_workspace");$("#profileRole").textContent=tr("profile_"+state.role);$("#profileName").textContent=state.role==="admin"?(state.lang==="fa"?"مدیر اصلی":"Main admin"):state.role==="reseller"?(state.lang==="fa"?"امیر رضایی":"Amir Rezaei"):(state.lang==="fa"?"همکار فروش":"Sales partner");$("#profileAvatar").textContent=state.role==="admin"?"م":state.role==="reseller"?"ا":"ه";$("#breadcrumbCurrent").textContent=tr("page_title_"+state.page)||tr("nav_"+state.page)||state.page;const options=$("#roleSelect").options;options[0].text=tr("role_admin");options[1].text=tr("role_reseller");options[2].text=tr("role_partner");applyStaticCopy();renderCustomers();renderOrders();applyRole();document.title=(state.lang==="fa"?"وایرپنل — ":"WirePanel — ")+(tr("page_title_"+state.page)||"WirePanel")}
function applyRole(){const restricted={partner:["customers","subscriptions","profiles"],reseller:[],admin:[]};$$("[data-roles]").forEach(el=>{el.hidden=!el.dataset.roles.split(/\s+/).includes(state.role)});$$(".nav-link[data-page]").forEach(el=>{el.hidden=!!restricted[state.role]?.includes(el.dataset.page)});if(state.role==="reseller"){$("#customerMetric").textContent="۸۴";$("#balanceMetric").textContent="۱۲٬۴۰۰٬۰۰۰"}else if(state.role==="admin"){$("#customerMetric").textContent="۱۲۸";$("#balanceMetric").textContent="۲۴٬۸۰۰٬۰۰۰"}if(state.role==="partner"){navigate("partner")}else if(state.page==="partner"){navigate("overview")}}
function navigate(page){state.page=page;const view=$("#view-"+page)||$("#view-not-found");$$(".page-view").forEach(x=>x.classList.remove("active"));view.classList.add("active");$$(".nav-link").forEach(x=>x.classList.toggle("active",x.dataset.page===page));$("#breadcrumbCurrent").textContent=tr("page_title_"+page)||$(".nav-link[data-page="+page+"] span")?.textContent||page;document.title=(tr("page_title_"+page)||"WirePanel")+" · WirePanel";window.scrollTo({top:0,behavior:"smooth"});$("#sidebar").classList.remove("mobile-open")}
function renderCustomers(){const tbody=$("#customerRows");if(!tbody)return;const q=($("#customerSearch")?.value||"").trim().toLocaleLowerCase();const filter=$("#customerFilter")?.value||"all";const display=x=>state.lang==="en"?(staticEn[x]||x):x;const visible=customers.filter(c=>(!q||(c.name+c.phone+c.server).toLocaleLowerCase().includes(q))&&(filter==="all"||(filter==="active"&&c.state!=="expired")||(filter==="near"&&c.used/c.limit>=.9)||(filter==="expired"&&c.state==="expired")));tbody.innerHTML=visible.map((c,i)=>`<tr><td><div class="customer-cell"><span class="avatar avatar-${c.color}">${c.initial}</span><span><b>${esc(display(c.name))}</b><small>${esc(c.phone)}</small></span></div></td><td><span class="state-pill ${c.state==="online"?"state-online":c.state==="expired"?"state-expired":"state-neutral"}"><i></i>${c.state==="online"?(state.lang==="fa"?"آنلاین":"Online"):c.state==="expired"?(state.lang==="fa"?"منقضی":"Expired"):(state.lang==="fa"?"آفلاین":"Offline")}</span></td><td><div class="usage-cell"><div class="usage-track"><i style="width:${Math.min(100,c.used/c.limit*100)}%;background:${c.used/c.limit>.9?"#e5a54a":"#83cbb4"}"></i></div><span>${c.used} / ${c.limit} GB</span></div></td><td><span class="expiry ${c.days<=3?"warning-text":""}">${c.days===0?(state.lang==="fa"?"پایان‌یافته":"Expired"):c.days+(state.lang==="fa"?" روز":" days")}</span></td><td>${esc(display(c.server))}</td><td><button class="icon-button subtle row-more" data-customer="${i}" aria-label="${state.lang==="fa"?"جزئیات":"Details"}">⋯</button></td></tr>`).join("");const count=$("#customerCount");if(count)count.textContent=tr("customer_count").replace("{shown}",visible.length.toLocaleString(state.lang==="fa"?"fa-IR":"en-US")).replace("{total}",state.lang==="fa"?"۱۲۸":"128");if(!visible.length)tbody.innerHTML=`<tr><td colspan="6" class="empty-row">${tr("empty_filter")}</td></tr>`}
function renderOrders(){const rows=$("#recentOrders");const all=$("#ordersRows");const display=x=>state.lang==="en"?(staticEn[x]||x):x;const markup=orders.map(o=>`<tr><td><div class="customer-cell"><span class="avatar avatar-mint">${display(o.name).slice(0,1)}</span><span><b>${esc(display(o.name))}</b></span></div></td><td>${esc(display(o.plan))}</td><td>${esc(display(o.date))}</td><td>${esc(display(o.amount))}</td><td><span class="state-pill ${o.status==="فعال"||o.status==="تکمیل‌شده"?"state-online":"state-pending"}">${esc(display(o.status))}</span></td></tr>`).join("");if(rows)rows.innerHTML=markup;if(all)all.innerHTML=orders.map((o,i)=>`<tr><td><code>WP-${(2400+i).toString()}</code></td><td>${esc(display(o.name))}</td><td>${esc(display(o.kind))}</td><td>${esc(display(o.plan))}</td><td>${esc(display(o.amount))}</td><td><span class="state-pill ${o.status==="فعال"||o.status==="تکمیل‌شده"?"state-online":"state-pending"}">${esc(display(o.status))}</span></td><td>${esc(display(o.date))}</td></tr>`).join("")}
function esc(v){return String(v).replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]))}
function toast(message){const el=$("#toast");el.textContent=message;el.classList.add("show");clearTimeout(state.toastTimer);state.toastTimer=setTimeout(()=>el.classList.remove("show"),2800)}
function showModal(title=tr("modal_title"),message=tr("modal_text")){const modal=$("#modalBackdrop");$("#modalTitle").textContent=title;$("#modalMessage").textContent=message;modal.hidden=false;$("#modalConfirm").focus()}
function closeModal(){$("#modalBackdrop").hidden=true}
function action(name){const messages={"bulk-create":"ساخت گروهی پس از اتصال امن بک‌اند فعال می‌شود.","template-studio":"استودیو قالب با پیش‌نمایش زنده، چیدمان، رنگ‌ها و قالب اختصاصی هر اشتراک در نسخهٔ متصل در دسترس خواهد بود.","create-customer":state.lang==="fa"?"فرم ساخت Peer جدید پس از اتصال API فعال می‌شود.":"Create peer form will be enabled after the API is connected.","create-order":state.lang==="fa"?"انتخاب پلن نمایشی است؛ پرداخت واقعی در این نسخه انجام نمی‌شود.":"Plan selection is a preview; no real payment is processed.","submit-order":tr("order_added"),"invite-reseller":"فرآیند دعوت امن نماینده در بک‌اند تکمیل می‌شود.","add-node":"مدیریت Node نیازمند اتصال سرویس WG_Panel است.","new-profile":"پروفایل‌های WireGuard بعد از اتصال بک‌اند قابل ذخیره می‌شوند.","connect-bot":"توکن ربات فقط از مسیر امن سرور تنظیم می‌شود.","backup-now":"فرمان پشتیبان‌گیری به پنل واقعی ارسال نشده است.","inspect-backup":"این نسخهٔ نمایشی فایل پشتیبان واقعی ندارد.","export":"دادهٔ نمونه‌ای در خروجی واقعی قرار نمی‌گیرد.","refresh":state.lang==="fa"?"دادهٔ نمایشی به‌روزرسانی شد.":"Demo data refreshed."};if(name==="refresh"){toast(messages[name]);return}showModal(state.lang==="fa"?"نسخهٔ نمایشی":"Preview",messages[name]||tr("demo_action"))}
document.addEventListener("click",e=>{const nav=e.target.closest("[data-page]");if(nav){navigate(nav.dataset.page);return}const link=e.target.closest(".nav-link");if(link){navigate(link.dataset.page);return}const act=e.target.closest("[data-action]");if(act){action(act.dataset.action);return}if(e.target.closest(".row-more")){showModal(state.lang==="fa"?"جزئیات سرویس":"Service details",state.lang==="fa"?"مصرف، زمان، وضعیت اتصال و عملیات Peer در این صفحه نمایش داده می‌شود.":"Usage, time, connection state, and peer actions appear here.")}});
$("#languageToggle").addEventListener("click",()=>{state.lang=state.lang==="fa"?"en":"fa";localize()});$("#roleSelect").addEventListener("change",e=>{state.role=e.target.value;localize()});$("#customerSearch").addEventListener("input",renderCustomers);$("#customerFilter").addEventListener("change",renderCustomers);$("#clearSearch").addEventListener("click",()=>{$("#customerSearch").value="";$("#customerFilter").value="all";renderCustomers()});$("#modalClose").addEventListener("click",closeModal);$("#modalCancel").addEventListener("click",closeModal);$("#modalConfirm").addEventListener("click",()=>{closeModal();toast(tr("demo_action"))});$("#modalBackdrop").addEventListener("click",e=>{if(e.target.id==="modalBackdrop")closeModal()});$("#menuToggle").addEventListener("click",()=>$("#sidebar").classList.toggle("mobile-open"));$$("[data-order-tab]").forEach(btn=>btn.addEventListener("click",()=>{$$("[data-order-tab]").forEach(x=>x.classList.toggle("active",x===btn));toast(state.lang==="fa"?"فهرست سفارش‌ها فیلتر شد.":"Order list filtered.")}));$("#usageRange").addEventListener("click",()=>toast(state.lang==="fa"?"داده‌های هفت روز اخیر":"Last 7 days"));document.addEventListener("keydown",e=>{if(e.key==="Escape")closeModal()});localize();
